__sd("data/apps/w/webfont-bundler.json",{"id":"webfont-bundler","name":"Webfont Bundler","tagline":"Create @font-face kits easily","blurb":"Webfont Bundler is a simple utility that allows you to generate woff, woff2 and the necessary CSS boilerplate from non-web font formats (otf and ttf).","description":"Webfont Bundler is a simple utility that allows you to generate woff, woff2 and the necessary CSS boilerplate from non-web font formats (otf and ttf).\n\nWebfont Bundler also includes a tool to Download fonts from Google Fonts for self-hosting.","developer":"Rafael Mardojai CM","icon":"https://dl.flathub.org/media/com/rafaelmardojai/WebfontKitGenerator/871562e942ab4d777e51ad676c84dab5/icons/128x128/com.rafaelmardojai.WebfontKitGenerator.png","screenshots":[{"full":"https://dl.flathub.org/media/com/rafaelmardojai/WebfontKitGenerator/871562e942ab4d777e51ad676c84dab5/screenshots/image-1_orig.png","thumb":"https://dl.flathub.org/media/com/rafaelmardojai/WebfontKitGenerator/871562e942ab4d777e51ad676c84dab5/screenshots/image-1_752x465@1.png","w":1050,"h":650},{"full":"https://dl.flathub.org/media/com/rafaelmardojai/WebfontKitGenerator/871562e942ab4d777e51ad676c84dab5/screenshots/image-2_orig.png","thumb":"https://dl.flathub.org/media/com/rafaelmardojai/WebfontKitGenerator/871562e942ab4d777e51ad676c84dab5/screenshots/image-2_752x465@1.png","w":1050,"h":650},{"full":"https://dl.flathub.org/media/com/rafaelmardojai/WebfontKitGenerator/871562e942ab4d777e51ad676c84dab5/screenshots/image-3_orig.png","thumb":"https://dl.flathub.org/media/com/rafaelmardojai/WebfontKitGenerator/871562e942ab4d777e51ad676c84dab5/screenshots/image-3_752x465@1.png","w":1050,"h":650},{"full":"https://dl.flathub.org/media/com/rafaelmardojai/WebfontKitGenerator/871562e942ab4d777e51ad676c84dab5/screenshots/image-4_orig.png","thumb":"https://dl.flathub.org/media/com/rafaelmardojai/WebfontKitGenerator/871562e942ab4d777e51ad676c84dab5/screenshots/image-4_752x465@1.png","w":1050,"h":650}],"categories":["Graphics & Design","Internet & Browsing"],"tags":["utility"],"license":"GPL-3.0-or-later","platforms":["linux"],"repo":"https://github.com/rafaelmardojai/webfont-kit-generator/","homepage":"https://apps.gnome.org/WebfontKitGenerator/","stars":null,"version":"1.3.0","updated":"2025-07-20","replaces":[],"install":[{"platform":"linux","distro":"linux","manager":"flatpak","label":"Flatpak","command":"flatpak install flathub com.rafaelmardojai.WebfontKitGenerator","note":"Works on every distribution, sandboxed and kept up to date for you.","recommended":true}],"sources":["flathub"],"flathubId":"com.rafaelmardojai.WebfontKitGenerator"});